<tr data-laporan-id="{{ $l->id }}" data-permintaan-id="{{ $l->permintaan_laporan_id }}" data-search="{{ strtolower($l->perihal.' '.($l->tujuanSatuan->nama ?? '')) }}" data-prioritas="{{ $l->prioritas }}">
